for task in tasks:
    format_params["task"] = task

    command = task.get("worker", {}).get("command", [])
    task["worker"]["command"] = [x.format(**format_params) for x in command]

    env = task.get("worker", {}).get("env", {})
    for k in env.keys():
        resolve_keyed_by(
            env,
            k,
            "flatpak envs",
            **{
                "release-level": release_level(
                    config.graph_config["release-branches"], config.params
                ),
                "project": config.params["project"],
            },
        )
        task["worker"]["env"][k] = env[k].format(**format_params)

    task["attributes"]["flatpak_name"] = task["worker"]["env"]["APP_ID"]

    yield task
